//! Parity between a whole VoxCPM2 run in `voxr_narrate` ([`speak_voxcpm`])
//! and the JavaScript `voxcpm` it ports.
//!
//! The fixture (`tests/fixtures/narration_speak_oracle.json`) is checked in
//! and was generated by `tests/tools/narration_oracle/take_speak.mjs`, which
//! runs a patched copy of the skill's own `voxcpm` end to end with the model
//! call, the judge and the recognizer of a reference recording stubbed. Each
//! scenario is a series of runs sharing one cache directory and one output:
//! a designed voice run fresh, rerun, re-rolled and reset by a new seed, a
//! user's recording, Hi-Fi with a recording and with a designed voice, and a
//! part that fails and splits. Each run here replays the same options
//! through [`speak_voxcpm`] with the same stubs, built bit for bit as
//! `common::signals` builds them, and compares every model and judge call in
//! order, every line printed, the voice's median pitch, the joined samples,
//! the duration, phrases, checks and problems, the `.takes.json` text, and
//! every file left with the hash of its bytes.

use std::path::Path;

use serde::Deserialize;
use voxr_narrate::{
    Error, HeardCheck, HeardWord, JudgedTake, ReferenceHearing, Result, SLOWER, SpeakRequest,
    SpeechEngine, Take, TakeJudge, TakeSpec, Transcribed, Verdict, VoiceReference, VoiceSource,
    VoxcpmSetup, js_json, pcm16_wav, read_takes_file, read_wav_file, resolve_seed, say,
    speak_voxcpm, text_seed,
};

mod common;
use common::signals::{self, Op, noise};
use common::take_files::{Call, Listed, OpJson, io, listing, render_json, take_signal};
use common::{assert_oracle_current, load_json, num};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_speak_oracle.json"
);
const ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/take_speak.mjs"
);

const RATE: u32 = 48000;

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Fixture {
    checkpoint: String,
    ref_id: String,
    design: Vec<usize>,
    recording: Recording,
    reference_words: Vec<String>,
    scenarios: Vec<Scenario>,
}

#[derive(Debug, Deserialize)]
struct Recording {
    n: usize,
    ops: Vec<OpJson>,
}

#[derive(Debug, Deserialize)]
struct Scenario {
    name: String,
    script: String,
    voice: String,
    style: String,
    hifi: bool,
    reference: bool,
    takes: Vec<TakeJson>,
    runs: Vec<Run>,
}

/// One text's stub take: its length, its tones, the words heard in it,
/// and its verdict.
#[derive(Debug, Deserialize)]
struct TakeJson {
    said: String,
    n: usize,
    tones: Vec<OpJson>,
    words: Vec<HeardWord>,
    fail: Option<String>,
    why: String,
    thumps: usize,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Run {
    name: String,
    seed: Option<f64>,
    reroll: Vec<usize>,
    random: Option<f64>,
    calls: Vec<Call>,
    judged: Vec<Judged>,
    messages: Vec<String>,
    voice_median: String,
    joined: String,
    duration: String,
    phrases: String,
    checks: String,
    problems: Vec<String>,
    voice_file: bool,
    takes_json: String,
    files: Vec<Listed>,
}

#[derive(Debug, Clone, PartialEq, Deserialize)]
struct Judged {
    text: String,
    seed: f64,
}

fn take_of<'a>(scenario: &'a Scenario, said: &str) -> Result<&'a TakeJson> {
    scenario
        .takes
        .iter()
        .find(|t| t.said == said)
        .ok_or_else(|| Error::DataError {
            reason: format!("scenario {} has no take for {said:?}", scenario.name),
        })
}

/// `1 + (seed % 997)`: the noise seed of a take made at `seed`.
fn noise_seed(seed: f64) -> u32 {
    1 + (seed as u64 % 997) as u32
}

/// Speaks as the oracle's stub model does, and records each call: the
/// design and each slower reference take a tone of the length `design`
/// names, every other take the scenario's table entry for its text.
struct Engine<'a> {
    scenario: &'a Scenario,
    design: &'a [usize],
    calls: Vec<Call>,
}

impl SpeechEngine for Engine<'_> {
    type Reference = ();

    fn speak(&mut self, request: &SpeakRequest<'_, ()>) -> Result<Take> {
        self.calls.push(Call::of(request)?);
        let slower = request
            .delivery
            .and_then(|d| SLOWER.iter().position(|s| *s == d))
            .map(|i| i + 1);
        let design = match (request.voice, slower) {
            (VoiceSource::Own { .. }, _) => Some(0),
            (_, Some(k)) => Some(k),
            _ => None,
        };
        let samples = match design {
            Some(k) => take_signal(self.design[k], false, 101 + k as u32),
            None => {
                let t = take_of(self.scenario, request.text)?;
                let mut ops: Vec<Op> = vec![noise(0, t.n, 0.00002, noise_seed(request.seed))];
                ops.extend(t.tones.iter().map(OpJson::op));
                signals::render(t.n, &ops)
            }
        };
        Ok(Take {
            samples,
            rate: RATE,
        })
    }
}

/// Judges as the oracle's stub judge does, and records each call; hears a
/// reference recording as the scenario's reference words.
struct Judge<'a> {
    scenario: &'a Scenario,
    run_seed: f64,
    reference_words: &'a [String],
    calls: Vec<Judged>,
}

impl TakeJudge for Judge<'_> {
    type Verdict = JudgedTake;

    fn judge(&mut self, spec: &TakeSpec, take: &Take) -> Result<JudgedTake> {
        let t = take_of(self.scenario, &say(&spec.text)?)?;
        self.calls.push(Judged {
            text: spec.text.clone(),
            seed: spec.seed,
        });
        let ok = match t.fail.as_deref() {
            Some("all") => false,
            Some("first") => spec.seed != text_seed(&spec.text, self.run_seed),
            _ => true,
        };
        let heard: Vec<&str> = t.words.iter().map(|w| w.text.as_str()).collect();
        Ok(JudgedTake {
            heard: HeardCheck {
                check: Verdict {
                    ok,
                    extra: Vec::new(),
                    missing: Vec::new(),
                    unsure: Some(Vec::new()),
                    why: if ok { String::new() } else { t.why.clone() },
                    badness: Some(if ok { 0.0 } else { 1.0 }),
                },
                doubt: Vec::new(),
                words: t.words.clone(),
                pauses: Vec::new(),
                heard: heard.join(" "),
            },
            take: take.clone(),
            seed: spec.seed,
            thumps: t.thumps,
            fixed: 0,
            clicks: Vec::new(),
        })
    }
}

impl ReferenceHearing for Judge<'_> {
    fn hear_reference(&mut self, _samples: &[f32], _rate: u32) -> Result<Transcribed> {
        Ok(Transcribed {
            words: self
                .reference_words
                .iter()
                .map(|w| HeardWord {
                    text: w.clone(),
                    start: 0.0,
                    end: 0.0,
                })
                .collect(),
            looped: false,
            duration: 0.0,
        })
    }
}

/// Reads a recording as 48 kHz mono samples.
fn decode(path: &Path) -> Result<Vec<f32>> {
    let take = read_wav_file(path)?;
    if take.rate != RATE {
        return Err(Error::DataError {
            reason: format!("{} is at {} Hz, not {RATE}", path.display(), take.rate),
        });
    }
    Ok(take.samples)
}

fn run_one(fixture: &Fixture, scenario: &Scenario, root: &Path, run: &Run) -> Result<()> {
    let name = format!("{} / {}", scenario.name, run.name);
    let cache = root.join("cache");
    let out = root.join("out.wav");
    let record = root.join("out.takes.json");
    let saved = std::fs::read_to_string(&record).unwrap_or_default();
    let run_seed = resolve_seed(run.seed, &read_takes_file(&saved), None).seed;
    let ref_path = root.join("ref.wav");
    let reference = scenario.reference.then(|| VoiceReference {
        path: &ref_path,
        id: fixture.ref_id.clone(),
    });
    let setup = VoxcpmSetup {
        asr_model: None,
        cache_dir: &cache,
        out: &out,
        voice: &scenario.voice,
        style: &scenario.style,
        reference: reference.as_ref(),
        seed: run.seed,
        config_seed: None,
        cfg: 1.6,
        steps: 16,
        hifi: scenario.hifi,
        language: None,
        rerolls: &run.reroll,
        lines: false,
        checkpoint: Some(fixture.checkpoint.as_str()),
        device: None,
    };
    let mut engine = Engine {
        scenario,
        design: &fixture.design,
        calls: Vec::new(),
    };
    let mut judge = Judge {
        scenario,
        run_seed,
        reference_words: &fixture.reference_words,
        calls: Vec::new(),
    };
    let mut random = || {
        run.random
            .unwrap_or_else(|| panic!("run {name} draws no random number"))
    };
    let got = speak_voxcpm(
        &scenario.script,
        &setup,
        &mut engine,
        &mut judge,
        &mut decode,
        &mut random,
    )?;

    assert_eq!(engine.calls, run.calls, "model calls, {name}");
    assert_eq!(judge.calls, run.judged, "judge calls, {name}");
    let messages: Vec<String> = got.log.iter().filter_map(|s| s.message()).collect();
    assert_eq!(messages, run.messages, "messages, {name}");
    assert_eq!(
        got.voice_median,
        num(&run.voice_median),
        "voice median, {name}"
    );
    assert_eq!(
        signals::fnv1a(&got.track.samples),
        run.joined,
        "joined, {name}"
    );
    assert_eq!(got.track.duration, num(&run.duration), "duration, {name}");
    assert_eq!(js_json(&got.track.phrases)?, run.phrases, "phrases, {name}");
    assert_eq!(js_json(&got.checks)?, run.checks, "checks, {name}");
    assert_eq!(got.problems, run.problems, "problems, {name}");
    assert_eq!(
        got.voice_file.is_some(),
        run.voice_file,
        "voice file, {name}"
    );
    let failed = got.checks.iter().filter(|c| !c.ok).count();
    assert_eq!(failed, got.problems.len(), "failed parts, {name}");
    assert_eq!(
        got.parts.len(),
        got.checks.len(),
        "parts and checks, {name}"
    );
    let takes = std::fs::read_to_string(&record).map_err(io("reading", &record))?;
    assert_eq!(takes, run.takes_json, "takes file, {name}");
    assert_eq!(listing(root)?, run.files, "files, {name}");
    Ok(())
}

fn run_scenario(fixture: &Fixture, scenario: &Scenario) -> Result<()> {
    let tmp = tempfile::tempdir().map_err(|e| Error::File {
        reason: format!("creating a temporary directory: {e}"),
    })?;
    let root = tmp.path();
    let cache = root.join("cache");
    std::fs::create_dir_all(&cache).map_err(io("creating", &cache))?;
    if scenario.reference {
        let rec = root.join("ref.wav");
        let x = render_json(fixture.recording.n, &fixture.recording.ops);
        std::fs::write(&rec, pcm16_wav(&x, RATE)?).map_err(io("writing", &rec))?;
    }
    for r in &scenario.runs {
        run_one(fixture, scenario, root, r)?;
    }
    Ok(())
}

#[test]
fn matches_javascript_on_every_run() -> Result<()> {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    assert!(!fixture.scenarios.is_empty(), "fixture must not be empty");
    for s in &fixture.scenarios {
        run_scenario(&fixture, s)?;
    }
    Ok(())
}

#[test]
fn oracle_fixture_is_current() {
    assert_oracle_current(ORACLE, FIXTURE);
}
